python - <<'PY'
import glob,re,os
pat_birth=re.compile(r'birth_date:\s*(?:\d{4}|.*194\d)')
pat_death=re.compile(r'death_date:\s*(?:200[1-9]|2010|2011)')
for f in glob.glob('en.wikipedia.org/*.txt'):
    txt=open(f,errors='ignore').read()
    if pat_birth.search(txt) and pat_death.search(txt):
        if 'German-born' in txt or 'born in Germany' in txt or 'Germany' in txt:
            print(os.path.basename(f))
